import { Component, Input, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Subscription } from 'rxjs';
import { DispositivoService } from '../../../services/dispositivo.service';

@Component({
  selector: 'simulador-simplificado-resultado',
  templateUrl: './simulador-simplificado-resultado.component.html',
  styleUrl: './simulador-simplificado-resultado.component.scss',
  standalone: true,
  imports: [
    CommonModule
  ]
})
export class SimuladorSimplificadoResultadoComponent implements OnInit {

  @Input() dados!: any;

  private readonly subscriptions: Subscription = new Subscription();
  
  dispositivo: string = '';

  constructor(
    private readonly dispositivoService: DispositivoService,
  ) { }

  ngOnInit(): void {

    this.setSubscriptions();
  }
  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  setSubscriptions() {
    this.subscriptions.add(
      this.dispositivoService.dispositivo$.subscribe((dispositivo) => {
        this.dispositivo = dispositivo;
      })
    );
  }

}
